r.deleted=0 AND r.id=r.root_id AND r.parent_id IS NULL AND r.template_id=#{q.templateId}
AND r.template_version=#{q.version}
AND r.status=#{q.status}
AND EXISTS (SELECT 1 FROM public.nocode_task_instance t
    WHERE t.root_id=r.id AND t.deleted=0 AND 
    AND (t.title ILIKE '%' || #{q.search} || '%' OR t.id ILIKE '%' || #{q.search} || '%'))

((t.project_json::jsonb->>'applicationId'=#{scope.context.applicationId}
  AND t.project_json::jsonb->>'objectId'=#{scope.context.objectId} AND t.project_json::jsonb->>'recordId'=#{scope.context.recordId})
OR (effective.business->'resource'->>'applicationId'=#{scope.context.applicationId}
  AND effective.business->'object'->>'objectId'=#{scope.context.objectId} AND effective.business->>'recordId'=#{scope.context.recordId})
OR linked.id IS NOT NULL
OR feedback_context.matched IS NOT NULL)

p.user_id=
t.assignee_id#{actor}
AND

, management_matches AS MATERIALIZED ( SELECT t.* FROM management_metrics t WHERE
t.assignee_id=#{m.employeeId} AND
(t.title ILIKE '%' || #{m.query.search} || '%' OR t.id ILIKE '%' || #{m.query.search} || '%' OR EXISTS (SELECT 1 FROM public.nocode_task_instance search_root WHERE search_root.id=t.root_id AND search_root.deleted=0 AND (search_root.title ILIKE '%' || #{m.query.search} || '%' OR search_root.id ILIKE '%' || #{m.query.search} || '%'))) AND
TRUE t.metric_pending t.metric_running t.metric_overdue t.metric_today t.metric_week t.metric_coordination NOT t.is_coordination AND t.effective_status NOT IN ('COMPLETED','CANCELLED')
t.assignee_id IS NULL AND t.effective_status NOT IN ('COMPLETED','CANCELLED') t.effective_status NOT IN ('COMPLETED','CANCELLED') AND t.expected_end::date < CURRENT_DATE t.effective_status='PENDING_ACCEPTANCE' t.effective_status NOT IN ('COMPLETED','CANCELLED') TRUE
), management_results AS ( SELECT t.* FROM management_matches t
SELECT t.* FROM public.nocode_task_instance t WHERE t.deleted=0 AND t.id=t.root_id AND t.parent_id IS NULL AND AND EXISTS (SELECT 1 FROM management_matches s WHERE s.root_id=t.id) AND t.creator=CAST(#{actor} AS varchar)
AND t.status NOT IN ('COMPLETED','CANCELLED') AND ()=#{m.query.status}
)

mapper.select:
SELECT EXISTS(SELECT 1 FROM public.nocode_task_instance t
    WHERE t.deleted=0 AND t.assignee_id=#{actor}
      AND t.business_json::jsonb->>'requestId'=#{request}
      AND t.business_json::jsonb->'resource'->>'applicationId'=#{resource.applicationId}
      AND t.business_json::jsonb->'resource'->>'applicationVersion'=CAST(#{resource.applicationVersion} AS text)
      AND t.business_json::jsonb->'resource'->>'applicationChecksum'=#{resource.applicationChecksum}
      AND t.business_json::jsonb->'resource'->>'resourceId'=#{resource.resourceId}
      AND t.business_json::jsonb->'object'->>'objectId'=#{object}
    UNION ALL
    SELECT 1 FROM public.nocode_task_entry_record e
    JOIN public.nocode_task_instance t ON t.id=e.task_id
    WHERE e.deleted=0 AND t.deleted=0 AND t.assignee_id=#{actor}
      AND e.creator=CAST(#{actor} AS varchar)
      AND e.business_json::jsonb->>'requestId'=#{request}
      AND e.business_json::jsonb->'resource'->>'applicationId'=#{resource.applicationId}
      AND e.business_json::jsonb->'resource'->>'applicationVersion'=CAST(#{resource.applicationVersion} AS text)
      AND e.business_json::jsonb->'resource'->>'applicationChecksum'=#{resource.applicationChecksum}
      AND e.business_json::jsonb->'resource'->>'resourceId'=#{resource.resourceId}
      AND e.business_json::jsonb->'object'->>'objectId'=#{object})
